<?php
require_once 'functions.php';require_role(['admin','kasir']);
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$act=$_POST['act'];$status=$act==='terima'?'diproses':'dibatalkan';$pdo->prepare("UPDATE tbl_transaksi SET status=? WHERE id_transaksi=? AND status='menunggu'")->execute([$status,$id]);flash('Status pesanan diperbarui.');go('kasir_pesanan.php');}
$rows=$pdo->query("SELECT t.*,p.nama_pelanggan FROM tbl_transaksi t LEFT JOIN tbl_pelanggan p ON p.id_pelanggan=t.id_pelanggan WHERE t.status IN('menunggu','diproses') ORDER BY t.id_transaksi DESC")->fetchAll();layout_header('Pesanan Masuk');
?>
<div class="page-title"><div><span class="eyebrow">LAYANAN KASIR</span><h1>Pesanan masuk</h1><p>Periksa pesanan online dan lanjutkan ke pembayaran.</p></div><a class="btn btn-primary" href="kasir_pos.php">Buka POS</a></div><div class="table-wrap"><table><thead><tr><th>Nomor</th><th>Pelanggan</th><th>Tanggal</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nomor_transaksi'])?></td><td><?=e($r['nama_pelanggan']??'-')?></td><td><?=e($r['tanggal'])?></td><td><?=rupiah($r['total_bayar'])?></td><td><?=e($r['status'])?></td><td><a class="btn btn-outline btn-sm" href="kasir_pos.php?id=<?=$r['id_transaksi']?>">Proses</a><?php if($r['status']==='menunggu'):?><form method="post" style="display:inline"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['id_transaksi']?>"><input type="hidden" name="act" value="terima"><button class="btn btn-primary btn-sm">Terima</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
